import {BasicResponse, GameController, GameControllerEvents, logger} from '@lumoragaming/slotcore';
import {ChickenGameControllerEvents} from 'src/ChickenGameControllerEvents';
import {GameMode} from 'src/gamedata/GameSpecificData';

export class ChickenGameController extends GameController {
    // game actions: main, nextStep, payout

    public async roundStart(cb: (result: BasicResponse) => void, bet: number, gameMode: GameMode): Promise<void> {
        const cheat = this.getCheatValue();

        const result = await this._playBridge.play({bet, cheat, action: 'main', data: {gameMode: gameMode}});

        if (result.hasOwnProperty('error')) {
            this._eventManager.emit(GameControllerEvents.ERROR_RECEIVED, result);
            return;
        }

        const allowedActions = result?.action?.allowedActions ? [...result.action.allowedActions] : [];
        const state: any = {...result.action?.state};
        const resObject: any = {balance: result.balance, roundId: result.roundId, ...result.action.result,
            allowedActions: allowedActions, state: state};

        cb && cb(resObject as BasicResponse);
        this._eventManager.emit(ChickenGameControllerEvents.STEP_RECEIVED);
    }

    public async step(cb: (result: BasicResponse) => void): Promise<void> {
        const cheat = this.getCheatValue();

        const result = await this._playBridge.play({cheat, action: 'nextStep'});
        if (result.hasOwnProperty('error')) {
            this._eventManager.emit(GameControllerEvents.ERROR_RECEIVED, result);
            return;
        }

        const resObject: any = {balance: result.balance, roundId: result.roundId, ...result.action};
        cb && cb(resObject as BasicResponse);
        this._eventManager.emit(ChickenGameControllerEvents.STEP_RECEIVED);
    }

    public async payout(cb: (result: BasicResponse) => void): Promise<void> {
        const result = await this._playBridge.play({action: 'payout'});
        if (result.hasOwnProperty('error')) {
            this._eventManager.emit(GameControllerEvents.ERROR_RECEIVED, result);
            return;
        }

        const resObject: any = {balance: result.balance, roundId: result.roundId, ...result.action};
        cb && cb(resObject as BasicResponse);
        this._eventManager.emit(ChickenGameControllerEvents.PAYOUT_RECEIVED);
    }
}