import {AutoplayBasicState} from '@lumoragaming/slotcore';
import {AutoplayHandlerEvents, AutoplayHandlerModule} from '@lumoragaming/slotcore';
import {AutoplayMenuEvents, GlobalStateEvents} from '@lumoragaming/slotcore';
import {GameAutoplayHandlerEvents} from 'src/autoplay/GameAutoplayHandlerEvents';
import {GameAutoplayHandlerModule} from 'src/autoplay/GameAutoplayHandlerModule';

export class GameAutoplayBasicState extends AutoplayBasicState<GameAutoplayHandlerModule> {

    protected setupEvents(): void {
        this.on(AutoplayMenuEvents.AUTOPLAY_MENU_ACCEPTED, this.onAutoStepsSettingsAccepted);
        this.on(GlobalStateEvents.CAN_SPIN, this.onGameRoundFinished);
    }

    protected onAutoStepsSettingsAccepted(eventID: string, spinsLeft: number, cashoutStep: number, selectedDifficulty: number): void {
        this.emit(AutoplayHandlerEvents.AUTOPLAY_STARTED, spinsLeft, cashoutStep, selectedDifficulty);
        this.module.startChickenAutoplay(spinsLeft, cashoutStep);
        this.emit(GameAutoplayHandlerEvents.AUTOPLAY_STEP)
        this.module.gotoState(AutoplayHandlerModule.IN_PROGRESS);
    }
}