import {AtlasNumbers, BasicView, GameUtils, ISpineAnimation, Timer, Tween} from "@lumoragaming/slotcore";
import {injectFromBase} from "inversify";

@injectFromBase()
export class ChickenView extends BasicView {

    // duration (ms) of the chicken's first step onto the road
    private static readonly FIRST_STEP_DURATION: number = 500;

    private static readonly IDLE_ADD_TIME: number = 5000;

    private _chicken: ISpineAnimation;

    private _currentMultiplier: ISpineAnimation;
    private _multiplierValue: AtlasNumbers;

    private _idleTimer: Timer;

    public init(): void {
        super.init();

        const chickenXOffset = this.getConfigValue('game.chickenXOffset');

        this._chicken = this.spineUtils.startSpineAnimationCreation('CHICKEN.json', 'IDLE', true)
            .position(-chickenXOffset, 0)
            .createAndStart();

        this._currentMultiplier = this.spineUtils.startSpineAnimationCreation('CURRENT_MULTIPLIER.json', 'IDLE', true)
            .createAndStart();
        this._multiplierValue = new AtlasNumbers(this.assets, 'COINS_');
        this._multiplierValue.showNumber('0');
        this.spineUtils.replaceSlotAttachment(this._currentMultiplier, 'SYMBOL_NUMBER', this._multiplierValue);

        this.spineUtils.replaceSlotAttachment(this._chicken, 'CURRENT_MULTIPLIER', this._currentMultiplier.spine);
        this.hideCurrentMultiplier();
    }

    public showCurrentMultiplier(): void {
        this._currentMultiplier.play('IDLE', 0, true);
    }

    public hideCurrentMultiplier(): void {
        this._currentMultiplier.play('INVISIBLE', 0, true);
    }

    public setMultiplierValue(value: number): void {
        this._multiplierValue.showNumber(`x${value}`);
    }

    public async playDead(): Promise<void> {
        this.resetIdle();
        this._chicken.play(`DEATH${GameUtils.randomInt(1, 3)}`, 0, false, 'IDLE');
        await this._chicken.getPromise(0);
        this.startIdleTimer();
    }

    public resetRound(): void {
        const chickenXOffset = this.getConfigValue('game.chickenXOffset');

        this._chicken.spine.position.set(-chickenXOffset, 0);
    }

    public async makeFirstStep(): Promise<void> {
        const tween = new Tween(this._chicken.spine)
            .to({x: 0}, ChickenView.FIRST_STEP_DURATION)
            .start();
        this.updateManager.add(tween);
        await tween.getPromise();
    }

    public async makeStep(): Promise<void> {
        this.resetIdle();

        this.soundPlayer.play('walking');
        this._chicken.play('WALKING', 0, true);
        await this.timeUtils.wait(500);
        this._chicken.play('IDLE', 0, true);

        this.startIdleTimer();
    }

    private resetIdle(): void {
        if (this._chicken.isTrackPlaying(1)) {
            this._chicken.stopTrack(1, false);
            if (this._idleTimer) {
                this.timeUtils.killTimer(this._idleTimer);
                this._idleTimer = null;
            }
        }
    }

    private startIdleTimer(): void {
        if (this._idleTimer) {
            this.timeUtils.killTimer(this._idleTimer);
            this._idleTimer = null;
        }

        this._idleTimer = this.timeUtils.createTimer(this.playRandomIdle.bind(this), ChickenView.IDLE_ADD_TIME);
    }

    private playRandomIdle(): void {
        this._chicken.play(`IDLE_RAND${GameUtils.randomInt(1, 3)}`, 1, false);
        this.startIdleTimer();
    }

}