import {HUDModule, MenuButtonEvents} from '@lumoragaming/slotcore';
import {GameHUDView} from 'src/hud/GameHUDView';
import {injectFromBase} from 'inversify';
import {GameSpecificData} from 'src/gamedata/GameSpecificData';

@injectFromBase()
export class GameHUDModule extends HUDModule<GameHUDView, GameSpecificData> {
    public async setNewCounterNumber(value: number): Promise<void> {
        await this.view.setNewStepNumber(value);
    }

    public async resetCounterNumber(): Promise<void> {
        await this.view.setNewStepNumber(0);
    }

    protected setupEvents(): void {
        super.setupEvents();

        this.onViewEmitEvent(GameHUDView.MENU_BUTTON_CLICKED, MenuButtonEvents.CLICKED);
    }
}