import {AssetsManager, DI, Game, GameData, CoreDI, GameController} from '@lumoragaming/slotcore';
import {BasicSlotAssetsManager} from 'src/BasicSlotAssetsManager';
import {GameSpecificData} from 'src/gamedata/GameSpecificData';
import {ChickenMainContainer} from 'src/ChickenMainContainer';
import {ChickenGameController} from 'src/ChickenGameController';

export class BasicSlotGame extends Game {

	protected createGameAssetsManager(): AssetsManager {
		return new BasicSlotAssetsManager();
	}

	protected createGameSpecificData(): GameData {
		return new GameSpecificData();
	}

	protected bindSlotMainUiClass(): void {
		this.diContainer
			.bind<ChickenMainContainer>(DI.MainUI)
			.to(ChickenMainContainer)
			.inSingletonScope();
	}

	protected async setupGameContainer(): Promise<void> {
		const gameController: ChickenGameController = new ChickenGameController();
		await gameController.initialize(this._device, this, this.diContainer.get(CoreDI.IEventManager));
		this.diContainer.bind<GameController>(DI.GameController).toConstantValue(gameController);
	}

}
