import {Module} from "@lumoragaming/slotcore";
import {injectFromBase} from "inversify";
import {GameSpecificData} from 'src/gamedata/GameSpecificData';
import {LosePresentationView} from 'src/modules/losepresentation/LosePresentationView';
import {LosePresentationEvents} from 'src/modules/losepresentation/LosePresentationEvents';

@injectFromBase()
export class LosePresentationModule extends Module<LosePresentationView, GameSpecificData> {
    public showPresentation(): void {
        this.view.showPresentation();
        this.emit(LosePresentationEvents.LOSE_PRESENTATION_STARTED);
    }

    protected setupEvents(): void {
        super.setupEvents();

        this.onViewEmitEvent(LosePresentationView.LOSE_PRESENTATION_FINISHED, LosePresentationEvents.LOSE_PRESENTATION_FINISHED);
    }
}