import {WinAmountPresentationModule, WinUtils} from "@lumoragaming/slotcore";
import {GameWinAmountPresentationView} from "src/modules/winamount/GameWinAmountPresentationView";
import {GameSpecificData} from "src/gamedata/GameSpecificData";
import {injectFromBase} from "inversify";

@injectFromBase()
export class GameWinAmountPresentationModule extends WinAmountPresentationModule<GameWinAmountPresentationView, GameSpecificData> {

    public playWin(winAmount: number): void {
        super.playWin(winAmount);
        if (winAmount > 0) {
            if (WinUtils.isWinNumberExcellentWin(this.gameData, winAmount)) {
                this.view.playExcellentWinSound();
            } else if (WinUtils.isWinNumberNiceWin(this.gameData, winAmount)) {
                this.view.playNormalWinSound();
            } else {
                this.view.playSmallWinSound();
            }
        }
    }
}