import {Alignment, GenericButton, ScreenOrientation, ScreenParams, UIElement, UIView} from "@lumoragaming/slotcore";
import {injectFromBase} from "inversify";

@injectFromBase()
export class CashoutButtonView extends UIView {

    public static readonly CASHOUT_BUTTON_CLICKED: string = 'SpinButtonView::CASHOUT_BUTTON_CLICKED';

    protected _cashOutButton: GenericButton;

    public init(): void {
        super.init();

        this.setupButtons();
        this.setupLayout();
    }

    public disableButton(): void {
        this._cashOutButton.button.visible = false;
    }

    public enableButton(): void {
        this._cashOutButton.button.visible = true;
    }

    public onResized(screenParams: ScreenParams): void {
        super.onResized(screenParams);

        this._cashOutButton.button.setButtonSkin(screenParams.isPortrait ? 'PORTRAIT' : 'LANDSCAPE');
    }

    protected setupButtons(): void {
        this._cashOutButton = this.createSpineCashOutButton();
        this.container.addChild(this._cashOutButton.button);
        this._cashOutButton.button.useLocalBoundsForHitArea = true;
        this._cashOutButton.button.setButtonSkin(this.screenOrientation === ScreenOrientation.PORTRAIT ? 'PORTRAIT' : 'LANDSCAPE');
    }

    protected createSpineCashOutButton(): GenericButton {
        return new GenericButton('CASHOUT_BUTTON.json', undefined, this.spineUtils, this.onCashOutButtonClicked.bind(this));
    }

    protected onCashOutButtonClicked(): void {
        this.soundPlayer.play('cash_out_button');
        this.emit(CashoutButtonView.CASHOUT_BUTTON_CLICKED);
    }

    protected setupLayout(): void {
        const bone = this.mainUI.getBoneFromUI('CASHOUT_BUTTON');
        const pmBone = this.mainUI.getBoneFromPortraitUI('CASHOUT_BUTTON');


        this._uiElements.push(new UIElement(this._cashOutButton.button,
            {x: 0, y: 0},
            {x: 0, y: 0},
            [Alignment.RIGHT],
            [Alignment.BOTTOM],
            {x: bone.scaleX, y: bone.scaleY},
            {x: pmBone.scaleX, y: pmBone.scaleY}
        ));
    }
}