import {injectFromBase} from "inversify";
import {CashoutButtonView} from 'src/modules/movingUI/cashout/CashoutButtonView';
import {CashoutButtonEvents} from 'src/modules/movingUI/cashout/CashoutButtonEvents';
import {AutoplayHandlerEvents, KeypadModule} from '@lumoragaming/slotcore';

@injectFromBase()
export class CashoutButtonModule extends KeypadModule<CashoutButtonView> {

    protected _isAutoplayOn: boolean = false;


    public init(view: CashoutButtonView, viewScreenName?: string): void {
        super.init(view, viewScreenName);

        this.view.disableButton();

    }

    public hideButton(): void {
        this.view.disableButton();
    }

    public showButton(): void {
        if (!this._isAutoplayOn) {
            this.view.enableButton();
        }
    }

    protected setupEvents(): void {
        super.setupEvents();

        this.onViewEmitEvent(CashoutButtonView.CASHOUT_BUTTON_CLICKED, CashoutButtonEvents.CASHOUT_BUTTON_CLICKED);
        this.on(CashoutButtonEvents.CASHOUT_BUTTON_CLICKED, this.onCashOutClicked);

        this.on(AutoplayHandlerEvents.AUTOPLAY_STARTED, this.onAutplayStarted);
        this.on(AutoplayHandlerEvents.AUTOPLAY_STOPPED, this.onAutplayStopped);
    }

    protected onAutplayStarted(): void {
        this._isAutoplayOn = true;
    }

    protected onAutplayStopped(): void {
        this._isAutoplayOn = false;
    }

    protected onCashOutClicked(): void {
        this.view.disableButton();
    }
}
