import {AutoplayInProgressState} from '@lumoragaming/slotcore';
import {GameGlobalEvents} from 'src/modules/globalstate/GameGlobalEvents';
import {GameAutoplayHandlerEvents} from 'src/autoplay/GameAutoplayHandlerEvents';
import {GameAutoplayHandlerModule} from 'src/autoplay/GameAutoplayHandlerModule';

export class GameAutoplayInProgressState extends AutoplayInProgressState<GameAutoplayHandlerModule> {


    protected setupEvents(): void {
        super.setupEvents();

        this.on(GameGlobalEvents.CHICKEN_STEP_FINISHED, this.onStepFinished);

    }

    protected async onStepFinished(): Promise<void> {
        if (this.gameData.isDead) {
            return ;
        }

        await this.timeUtils.wait(100);
        if (this.gameData.currentStep >= this.module.cashoutOnStep) {
            this.emit(GameAutoplayHandlerEvents.AUTOPLAY_CASHOUT);
        } else {
            this.emit(GameAutoplayHandlerEvents.AUTOPLAY_STEP)
        }
    }
}