import {GlobalStateSpinModule} from 'src/modules/globalstate/GlobalStateSpinModule';
import {
	BigWinEvents,
	BigWinModule,
	CompleteResponse,
	GlobalModuleState,
	GlobalStateEvents,
	IEventManager,
	WinAmountPresentationEvents,
} from '@lumoragaming/slotcore';
import {CashoutButtonModule} from 'src/modules/movingUI/cashout/CashoutButtonModule';
import {ChickenModule} from 'src/modules/chicken/ChickenModule';
import {RoadModule} from 'src/modules/road/RoadModule';
import {GameHUDModule} from 'src/hud/GameHUDModule';
import {ChickenKeypadController} from "../../../keypadController/ChickenKeypadController";
import {GameSoundController} from "../../../sounds/GameSoundController";
import {GameWinAmountPresentationModule} from "src/modules/winamount/GameWinAmountPresentationModule";

export class GlobalStateWin extends GlobalModuleState<GlobalStateSpinModule> {

	protected _winAmountModule!: GameWinAmountPresentationModule;
	protected _bigWinModule!: BigWinModule;
	protected _spinButtonModule!: CashoutButtonModule;
	protected _hudModule!: GameHUDModule;
	protected _chickenModule!: ChickenModule;
	protected _roadModule!: RoadModule;
	protected _keypadController!: ChickenKeypadController;
	protected _soundController!: GameSoundController;

	constructor(module: GlobalStateSpinModule, name: string, eventManager: IEventManager) {
		super(module, name, eventManager);

		this._winAmountModule = module.diContainer.get(GameWinAmountPresentationModule);
		this._bigWinModule = module.diContainer.get(BigWinModule);
		this._spinButtonModule = module.diContainer.get(CashoutButtonModule);
		this._hudModule = module.diContainer.get(GameHUDModule);
		this._chickenModule = module.diContainer.get(ChickenModule);
		this._roadModule = module.diContainer.get(RoadModule);
		this._keypadController = module.diContainer.get(ChickenKeypadController);
		this._soundController = module.diContainer.get(GameSoundController);
	}

	public async onEnterState(): Promise<void> {
		this._soundController.fadeOutMusic();
		this._chickenModule.hideCurrentMultiplier();

		if (this.gameData.isNumberBigWin(this.gameData.getTotalWin())) {
			this._bigWinModule.play(this.gameData.getTotalWin());
			this.queueEvents.addFunctionCallingEventToWaitingList(BigWinEvents.FINISHED, this.onBigWinFinished.bind(this));
		} else if (this.gameData.getTotalWin() > 0) {
			this._winAmountModule.playWin(this.gameData.getTotalWin());
			this.queueEvents.addFunctionCallingEventToWaitingList(WinAmountPresentationEvents.WIN_ANIMATION_EXIT_FINISHED, this.onWinPresentationFinished.bind(this));
		} else {
			throw new Error('GlobalStateWin win is 0 shoould not be possible');
			// this.actionAfterWinPresentation();
		}
	}

	public onLeaveState(): void {
	}

	protected onWinPresentationFinished(): void {
		this.actionAfterWinPresentation();
	}

	protected onBigWinFinished(): void {
		this.actionAfterWinPresentation();
	}

	protected async actionAfterWinPresentation(): Promise<void> {
		this._hudModule.updateWin(this.gameData.getSpinWin());
		await this.sendComplete();
		this.decideOnNextStateAfterWinPresentation();
	}

	protected async sendComplete(): Promise<void> {
		await this.gameController.complete((data: CompleteResponse) => {
			this.gameData.reactOnComplete(data);
		});
		this._hudModule.updateBalance();

	}

	protected decideOnNextStateAfterWinPresentation(): void {
		this.gameData.resetSteps();
		this._roadModule.resetRound();
		this._chickenModule.resetRound();

		this.emit(GlobalStateEvents.CAN_SPIN);

		this._keypadController.enableOnCashoutFinished();
		this.gotoState(GlobalStateSpinModule.IDLE);
	}

	protected setupEvents(): void {
	}

}
