import {AutoplayHandlerModule, BasicView} from '@lumoragaming/slotcore';
import {ChickenEvents} from 'src/modules/chicken/ChickenEvents';
import {injectFromBase} from 'inversify';
import {GameAutoplayBasicState} from 'src/autoplay/states/GameAutoplayBasicState';
import {GameAutoplayInProgressState} from 'src/autoplay/states/GameAutoplayInProgressState';
import {GameSpecificData} from 'src/gamedata/GameSpecificData';
import {GameAutoplayHandlerEvents} from 'src/autoplay/GameAutoplayHandlerEvents';

@injectFromBase()
export class GameAutoplayHandlerModule extends AutoplayHandlerModule<BasicView, GameSpecificData> {

    private _cashoutOnStep: number = 0;

    public startChickenAutoplay(spinsLeft: number, cashoutOnStep: number): void  {
        this._cashoutOnStep = cashoutOnStep - 1;
        this.startAutoplay(spinsLeft);
    }

    protected setupStates(): void {
        super.setupStates();

        this.addState(new GameAutoplayBasicState(this, AutoplayHandlerModule.BASIC));
        this.addState(new GameAutoplayInProgressState(this, AutoplayHandlerModule.IN_PROGRESS));
    }

    protected setupEvents(): void {
        super.setupEvents();

        this.on(ChickenEvents.STEP_STARTED, this.onSpinStarted);
    }

    protected startAutoplaySpin(): void {
        super.startAutoplaySpin();
        this.eventManager.emit(GameAutoplayHandlerEvents.AUTOPLAY_STEP);
    }

    public get cashoutOnStep(): number {
        return this._cashoutOnStep;
    }
}