import {BigWinEvents, SoundController} from '@lumoragaming/slotcore';
import {GameHUDModule} from 'src/hud/GameHUDModule';
import {injectFromBase} from 'inversify';

@injectFromBase()
export class GameSoundController extends SoundController {

    public playStandingMusic(): void {
        this.soundPlayer.fadeCurrentMusicTo('main_music_loop1');
    }

    public playWalkingMusic(): void {
        this.soundPlayer.fadeCurrentMusicTo('main_music_loop2');
    }

    public fadeOutMusic(): void {
        this.soundPlayer.stopMusic();
    }

    protected setupHUDModule(): void {
        this._hudModule = this.diContainer.get(GameHUDModule);
        this._hudModule.soundButtonStateSwitched = this.onButtonStateSwitched.bind(this);
    }

    protected setupMenuModule(): void {

    }

    protected setupEvents() {
        super.setupEvents();

        this.on(BigWinEvents.BIG_WIN_STARTED, this.onBigWinStarted);
        this.on(BigWinEvents.FINISHED, this.onBigWinFinished);
        this.on(BigWinEvents.TRANSITION_STARTED, this.onBigWinLevelup);
        this.on(BigWinEvents.COUNTUP_STARTED, this.onBigWinCountupStarted);
        this.on(BigWinEvents.SKIP_CLICKED, this.onBigWinCountupEnded);
        this.on(BigWinEvents.COUNTUP_FINISHED, this.onBigWinCountupEnded);
    }

    protected async onBigWinStarted(): Promise<void> {
        this.soundPlayer.play('big_win_intro');
        await this.timeUtils.wait(this.soundPlayer.getSoundLength('big_win_intro') * 1000);
        this.soundPlayer.fadeCurrentMusicTo('big_win_loop', 0);
    }

    protected onBigWinCountupStarted(): void {
        this.soundPlayer.play('big_win_coin_loop', true);
    }

    protected onBigWinCountupEnded(): void {
        this.soundPlayer.stopMusic();
        this.soundPlayer.stop('big_win_coin_loop');
        this.soundPlayer.play('big_win_end');
    }

    protected onBigWinFinished(): void {
    }

    protected onBigWinLevelup(): void {
        this.soundPlayer.play('big_win_levelup');
    }
}