import {injectFromBase} from 'inversify';
import {Alignment, GenericButton, UIElement, UIView} from '@lumoragaming/slotcore';
import {GameMode} from 'src/gamedata/GameSpecificData';

@injectFromBase()
export class DifficultyButtonView extends UIView {

    public static readonly DIFFICULTY_EASY_SELECTED: string = 'DifficultyButtonView::DIFFICULTY_EASY_SELECTED';
    public static readonly DIFFICULTY_MEDIUM_SELECTED: string = 'DifficultyButtonView::DIFFICULTY_MEDIUM_SELECTED';
    public static readonly DIFFICULTY_HARD_SELECTED: string = 'DifficultyButtonView::DIFFICULTY_HARD_SELECTED';
    public static readonly DIFFICULTY_BUTTON_CLICKED: string = 'DifficultyButtonView::DIFFICULTY_BUTTON_CLICKED';

    protected _quickPlayButton: GenericButton;

    public init(): void {
        super.init();

        this.setupBetButton();
        this.setupLayout();
    }

    public forceSetDifficulty(gameMode: GameMode): void {
        switch (gameMode) {
            case GameMode.EASY: {
                this.setEasyMode();
                break;
            }
            case GameMode.MEDIUM: {
                this.setMediumMode();
                break;
            }
            case GameMode.HARD: {
                this.setHardMode();
                break;
            }
            default:
                throw new Error(`Unknown gameMode: ${gameMode}`);
        }
    }

    public disableButton(): void {
        this._quickPlayButton.button.disable();
    }

    public enableButton(): void {
        this._quickPlayButton.button.enable();
    }

    public setEasyMode(): void {
        this.spineUtils.setSkinOnAnimation(this._quickPlayButton.button.spineAnimation, 'LOW');
        this.emit(DifficultyButtonView.DIFFICULTY_EASY_SELECTED);
        this.emit(DifficultyButtonView.DIFFICULTY_BUTTON_CLICKED, GameMode.EASY);
    }

    public setMediumMode(): void {
        this.spineUtils.setSkinOnAnimation(this._quickPlayButton.button.spineAnimation, 'MEDIUM');
        this.emit(DifficultyButtonView.DIFFICULTY_MEDIUM_SELECTED);
        this.emit(DifficultyButtonView.DIFFICULTY_BUTTON_CLICKED, GameMode.MEDIUM);
    }

    public setHardMode(): void {
        this.spineUtils.setSkinOnAnimation(this._quickPlayButton.button.spineAnimation, 'HARD');
        this.emit(DifficultyButtonView.DIFFICULTY_HARD_SELECTED);
        this.emit(DifficultyButtonView.DIFFICULTY_BUTTON_CLICKED, GameMode.HARD);
    }

    protected setupLayout(): void {
        const bone = this.mainUI.getBoneFromUI('DIFFICULTY_BUTTON');
        const pmBone = this.mainUI.getBoneFromPortraitUI('DIFFICULTY_BUTTON');

        /*
        it's important to pass the this._betButton.button not this._betButton.button.spine!
        otherwise hitArea would be misaligned, SpineButton.ts:
        this._generatedHitArea = new Rectangle(bounds.width * -0.5, bounds.height * -0.5, bounds.width, bounds.height);
		this.hitArea = this._generatedHitArea;
         */
        this._uiElements.push(new UIElement(this._quickPlayButton.button,
            {x: 0, y: 0},
            {x: 0, y: 0},
            [Alignment.RIGHT],
            [Alignment.BOTTOM],
            {x: bone.scaleX, y: bone.scaleY},
            {x: pmBone.scaleX, y: pmBone.scaleY},
        ));
    }

    protected setupBetButton(): void {
        this._quickPlayButton = this.createSpineButton();

        this.container.addChild(this._quickPlayButton.button);
    }

    protected createSpineButton(): GenericButton {
        return new GenericButton('DIFFICULTY_BUTTON.json', 'LOW', this.spineUtils, this.onButtonClicked.bind(this));
    }

    protected onButtonClicked(): void {
        if (this._quickPlayButton.button.spineAnimation.skeleton.skin?.name === 'LOW') {
            this.setMediumMode();
        } else if (this._quickPlayButton.button.spineAnimation.skeleton.skin?.name === 'MEDIUM') {
            this.setHardMode();
        } else {
            this.setEasyMode();
        }
    }

}
