import {
    BasicView,
    HALF_SCREEN_HEIGHT,
    HALF_SCREEN_WIDTH, ISpineAnimation,
    SCREEN_HEIGHT,
    SCREEN_WIDTH, Timer
} from "@lumoragaming/slotcore";
import {injectFromBase} from "inversify";
import {Container, Graphics, Text, TextStyleOptions} from "pixi.js";

export const loseScreenTextStyle: TextStyleOptions = {
    fontFamily: 'Poppins SemiBold',
    fontSize: 20,
    fill: '#FFCC00',
    align: 'center',
};

@injectFromBase()
export class LosePresentationView extends BasicView {

    public static readonly LOSE_PRESENTATION_FINISHED: string = 'LosePresentationView::LOSE_PRESENTATION_FINISHED';

    protected _currentTimer: Timer;

    protected _currentScreen: ISpineAnimation;

    public async showPresentation(): Promise<void> {

        const back = new Graphics()
            .rect(-HALF_SCREEN_WIDTH * 2, -HALF_SCREEN_HEIGHT * 2, SCREEN_WIDTH * 2, SCREEN_HEIGHT * 2)
            .fill({color: 0x000000, alpha: 0.5});
        this.container.addChild(back);

        this._currentScreen = this.spineUtils.startSpineAnimationCreation('DEATH_SCREEN.json', 'ENTER', false)
            .chainIdleAnimation('IDLE')
            .createAndStart();

        await this._currentScreen.getPromise(0);

        const text = new Text({text: 'YOU LOSE\nClick to continue', style: loseScreenTextStyle});
        text.anchor.set(0.5);
        this.spineUtils.replaceSlotAttachment(this._currentScreen, 'TXT_CONTINUE', text);

        this._currentScreen.spine.interactive = true;

        this._currentScreen.spine.on('tap', this.hidePresentation.bind(this));
        this._currentScreen.spine.on('click', this.hidePresentation.bind(this));

        this._currentTimer = this.timeUtils.createTimer(() => {
            this.hidePresentation();
        }, 1000);

    }

    public async hidePresentation(): Promise<void> {
        this._currentTimer.stop();

        this._currentScreen.play('EXIT', 0, false, 'IDLE');
        await this._currentScreen.getPromise(0);

        this.container.removeChildren();
        this.emit(LosePresentationView.LOSE_PRESENTATION_FINISHED);
    }
}