import {
	BasicInitResponse,
	BasicResponse,
	ConfigResponse,
	GameData,
	GameUtils, logger, State,
} from '@lumoragaming/slotcore';


export interface GameConfigResponse extends ConfigResponse {
	deathChance: number;
	multipliers: number[][];
}

export interface GameState extends State {
	isDead: boolean;
	currentStep: number;
	gameMode: GameMode;
}

export interface GameBasicResponse extends BasicResponse {
	isDead: boolean;
	currentStep: number;
	win: number;
}

export enum GameMode {
	EASY = 0,
	MEDIUM = 1,
	HARD = 2,
}

export type GameInitResponse = BasicInitResponse<GameBasicResponse, GameState, GameConfigResponse>;

export class GameSpecificData extends GameData {

	private _currentStep: number = -1;
	private _isDead: boolean = false;

	private _currentGameMode: GameMode = GameMode.EASY;

	private _multipliers: number[][] = [[], [], []];

	public resetSteps(): void {
		this._currentStep = -1;
		this._isDead = false;
	}

	public hasReachedFinalPosition(): boolean {
		return this._currentStep + 1 >= 20;
	}

	public reactOnCashOut(data: GameBasicResponse): void {
		this._lastSpinResponse = data;

		if (data?.hasOwnProperty('balance') && typeof data?.balance === 'number') {
			this._balance = data.balance;
		}

		if (data?.roundId) {
			this._roundID = data.roundId;
		}

		this._totalWin = this._currentWin = data.win;

		if (!__PRODUCTION__) {
			logger.info('step data:');
			logger.info(data);
		}
	}

	public reactOnStep(data: GameBasicResponse): void {
		this._lastSpinResponse = data;

		if (data?.hasOwnProperty('balance') && typeof data?.balance === 'number') {
			this._balance = data.balance;
		}

		if (data?.roundId) {
			this._roundID = data.roundId;
		}

		this._totalWin = this._currentWin = data.win;

		this._isDead = data.isDead;
		this._currentStep = data.currentStep;

		if (!__PRODUCTION__) {
			logger.info('step data:');
			logger.info(data);
		}
	}

	public reactOnPayout(data: BasicResponse): void {
		this._lastSpinResponse = data;

		if (!__PRODUCTION__) {
			logger.info('payout data:');
			logger.info(data);
		}
	}

	protected setupGameFacts(): void {
	}

	protected initializeServerSymbols(): void {
	}

	protected afterInitRestoreSetup(data: BasicInitResponse): void {
		if (this.hasRestore) {
			/*if (this._currentFreeSpin >= 0) {
				this.parseSpin(this._freeSpins[this._currentFreeSpin]);
			} else {
				this.parseSpin(data.restore.actions[0].result.baseSpin, data.restore.actions[0].result);
			}*/ // TODO: restore stuff here
		}
	}

	protected parseState(stateData: GameState): void {
		if (stateData && !stateData.isDead) {
			this._currentStep = stateData.currentStep;
			this._currentGameMode = stateData.gameMode;
		}
	}

	protected parseInit(data: BasicInitResponse) {
		super.parseInit(data);

		// to make sure we don't have any old data
		if (!data.restore) {
			this._currentStep = -1;
		}
	}

	protected parseOtherInitData(data: GameInitResponse): void {
		super.parseOtherInitData(data);

		this._multipliers[GameMode.EASY] = [...data.config.multipliers[GameMode.EASY]];
		this._multipliers[GameMode.MEDIUM] = [...data.config.multipliers[GameMode.MEDIUM]];
		this._multipliers[GameMode.HARD] = [...data.config.multipliers[GameMode.HARD]];
	}

	protected parseConfigReelgrid(data: BasicInitResponse): void {
		
	}

	protected parseConfigPaytable(data: BasicInitResponse): void {

	}

	public get currentStep(): number {
		return this._currentStep;
	}

	public get isDead(): boolean {
		return this._isDead;
	}

	public get multipliers(): number[][] {
		return this._multipliers;
	}

	public get currentGameMode(): GameMode {
		return this._currentGameMode;
	}

	public set currentGameMode(value: GameMode) {
		this._currentGameMode = value;
	}
}
