import {injectFromBase} from 'inversify';
import {DifficultyButtonView} from 'src/modules/difficulty/DifficultyButtonView';
import {AutoplayHandlerEvents, KeypadModule} from '@lumoragaming/slotcore';
import {GameMode, GameSpecificData} from 'src/gamedata/GameSpecificData';
import {DifficultyButtonEvents} from 'src/modules/difficulty/DifficultyButtonEvents';

@injectFromBase()
export class DifficultyButtonModule extends KeypadModule<DifficultyButtonView, GameSpecificData> {


	public restore(): void {
		super.restore();

		this.view.forceSetDifficulty(this.gameData.currentGameMode);
	}

	protected setupEvents(): void {
		super.setupEvents();

		this.onView(DifficultyButtonView.DIFFICULTY_EASY_SELECTED, this.onEasyModeSelected);
		this.onView(DifficultyButtonView.DIFFICULTY_MEDIUM_SELECTED, this.onMediumModeSelected);
		this.onView(DifficultyButtonView.DIFFICULTY_HARD_SELECTED, this.onHardModeSelected);
		this.onViewEmitEvent(DifficultyButtonView.DIFFICULTY_BUTTON_CLICKED, DifficultyButtonEvents.DIFFICULTY_BUTTON_CLICKED);

		this.on(AutoplayHandlerEvents.AUTOPLAY_STARTED, this.onAutoplayStarted);
	}

	protected onButtonVisibilityChanged(isVisible: boolean): void {
		// DO NOTHING HERE
	}

	protected onAutoplayStarted(eventID: string, spinsLeft: number, cashoutStep: number, selectedDifficulty: number): void {
		this.view.forceSetDifficulty(selectedDifficulty);
	}

	protected onEasyModeSelected(): void {
		this.gameData.currentGameMode = GameMode.EASY;
	}

	protected onMediumModeSelected(): void {
		this.gameData.currentGameMode = GameMode.MEDIUM;
	}

	protected onHardModeSelected(): void {
		this.gameData.currentGameMode = GameMode.HARD;
	}
}
