import {WinAmountPresentationView, WinSize} from "@lumoragaming/slotcore";
import {injectFromBase} from "inversify";

@injectFromBase()
export class GameWinAmountPresentationView extends WinAmountPresentationView {

    public playExcellentWinSound(): void {
        this.soundPlayer.play('win_nice');
    }

    public playNormalWinSound(): void {
        this.soundPlayer.play('win_nice');
    }

    public playSmallWinSound(): void {
        this.soundPlayer.play('win_small');
    }


    public playWinNumberCounter(finalNumber: number, playBigNumbers: boolean, isCounting: boolean, winType: WinSize): void {
        if (isCounting) {
            this.soundPlayer.play('countup_loop', true);
        }
        super.playWinNumberCounter(finalNumber, playBigNumbers, isCounting, winType);
    }


    public playWinEndAnimation(): void {
        if (this._isCounting) {
        this.soundPlayer.play('countup_end');
        }
        this.soundPlayer.stop('countup_loop');

        super.playWinEndAnimation();
    }
}