import {GlobalStateSpinModule} from 'src/modules/globalstate/GlobalStateSpinModule';
import {
	AuthData,
	BasicInitResponse,
	CurrencyFormatter,
	DI,
	GameControllerEvents,
	GlobalModuleState,
	IEventManager,
	RestoreScreenEvents,
	RestoreScreenModule,
	StartScreenEvents,
} from '@lumoragaming/slotcore';
import {CashoutButtonModule} from 'src/modules/movingUI/cashout/CashoutButtonModule';
import {GameHUDModule} from 'src/hud/GameHUDModule';
import {ChickenModule} from "../../chicken/ChickenModule";

export class GlobalStateInit extends GlobalModuleState<GlobalStateSpinModule> {
	protected _hudModule!: GameHUDModule;
	protected _spinButtonModule!: CashoutButtonModule;
	protected _restoreScreenModule!: RestoreScreenModule;
	protected _chickenModule!: ChickenModule;

	protected _currencyFormatter: CurrencyFormatter;

	constructor(module: GlobalStateSpinModule, name: string, eventManager: IEventManager) {
		super(module, name, eventManager);

		this._hudModule = module.diContainer.get(GameHUDModule);
		this._spinButtonModule = module.diContainer.get(CashoutButtonModule);
		this._restoreScreenModule = module.diContainer.get(RestoreScreenModule);
		this._chickenModule = module.diContainer.get(ChickenModule);

		this._currencyFormatter = module.diContainer.get(DI.CurrencyFormatter)
	}

	public async onEnterState(): Promise<void> {
		await this.gameController.auth((result: AuthData) => {
			this.gameData.reactOnAuth(result);
			this._currencyFormatter.setCurrencyData(this.gameData.currencyInfo);
		});
		await this.gameController.init((result: BasicInitResponse) => {
			this.gameData.reactOnInit(result);
		});

		this.queueEvents.addFunctionCallingEventToWaitingList(StartScreenEvents.EXIT_FINISHED, this.onStartScreenExitFinished.bind(this));
	}

	public onLeaveState(): void {
	}

	protected onStartScreenExitFinished(): void {
		this.gameController.executeRestores();

		if (this.gameData.hasRestore) {
			this._restoreScreenModule.showRestoreMessage();
			this.queueEvents.addFunctionCallingEventToWaitingList(RestoreScreenEvents.RESTORE_CLOSED, this.onRestoreMessageClosed.bind(this));
		}
	}

	protected onRestoreMessageClosed(): void {
		this._chickenModule.showMultiplier(this.gameData.multipliers[this.gameData.currentGameMode][this.gameData.currentStep]);
		this._hudModule.setNewCounterNumber(this.gameData.currentStep + 1);
	}

	protected setupEvents(): void {
		this.on(GameControllerEvents.INIT_RECEIVED, this.onInitReceived);
	}

	protected onInitReceived(): void {
		if (this.gameData.hasRestore) {
			this.gotoState(GlobalStateSpinModule.STEP_IDLE);
		} else {
			this.gotoState(GlobalStateSpinModule.IDLE);
		}
	}

}
