import {injectFromBase} from "inversify";
import {KeypadModule} from '@lumoragaming/slotcore';
import {GoButtonView} from 'src/modules/movingUI/go/GoButtonView';
import {GoButtonEvents} from 'src/modules/movingUI/go/GoButtonEvents';

@injectFromBase()
export class GoButtonModule extends KeypadModule<GoButtonView> {
    public init(view: GoButtonView, viewScreenName?: string): void {
        super.init(view, viewScreenName);

        this.resetGame();
    }

    public resetGame(): void {
        this.view.showGoButton();
    }

    protected setupEvents(): void {
        super.setupEvents();

        this.onViewEmitEvent(GoButtonView.GO_BUTTON_CLICKED, GoButtonEvents.GO_BUTTON_CLICKED);
    }
}
