import {Alignment, GenericButton, ScreenOrientation, ScreenParams, UIElement, UIView} from "@lumoragaming/slotcore";
import {injectFromBase} from "inversify";

@injectFromBase()
export class GoButtonView extends UIView {

    public static readonly GO_BUTTON_CLICKED: string = 'GoButtonView::GO_BUTTON_CLICKED';

    protected _goButton: GenericButton;

    public init(): void {
        super.init();

        this.setupButtons();
        this.setupLayout();
    }

    public disableButton(): void {
        this._goButton.button.disable();
    }

    public enableButton(): void {
        this._goButton.button.enable();
    }

    public hideGoButton(): void {
        this._goButton.button.visible = false;
    }

    public showGoButton(): void {
        this._goButton.button.visible = true;
    }


    public onResized(screenParams: ScreenParams): void {
        super.onResized(screenParams);

        this._goButton.button.setButtonSkin(screenParams.isPortrait ? 'PORTRAIT' : 'LANDSCAPE');
    }

    protected setupButtons(): void {
        this._goButton = this.createSpineGoButton();
        this.container.addChild(this._goButton.button);
        this._goButton.button.useLocalBoundsForHitArea = true;
        this._goButton.button.setButtonSkin(this.screenOrientation === ScreenOrientation.PORTRAIT ? 'PORTRAIT' : 'LANDSCAPE');
    }

    protected createSpineGoButton(): GenericButton {
        return new GenericButton('GO_BUTTON.json', undefined, this.spineUtils, this.onGoButtonClicked.bind(this));
    }

    protected onGoButtonClicked(): void {
        this.soundPlayer.play('go_button');
        this.emit(GoButtonView.GO_BUTTON_CLICKED);
    }

    protected setupLayout(): void {
        const bone = this.mainUI.getBoneFromUI('GO_BUTTON');
        const pmBone = this.mainUI.getBoneFromPortraitUI('GO_BUTTON');

        this._uiElements.push(new UIElement(this._goButton.button,
            {x: 0, y: 0},
            {x: 0, y: 0},
            [Alignment.RIGHT],
            [Alignment.BOTTOM],
            {x: bone.scaleX, y: bone.scaleY},
            {x: pmBone.scaleX, y: pmBone.scaleY}
        ));
    }
}